def move_curated_profiles_to_separate_models(apps, schema_editor):
    CuratedProfile = apps.get_model("main", "CuratedProfile")
    BrideProfile = apps.get_model("main", "BrideProfile")
    GroomProfile = apps.get_model("main", "GroomProfile")
    database = schema_editor.connection.alias

    for curated in CuratedProfile.objects.using(database).all():
        profile_model = BrideProfile if curated.gender == "bride" else GroomProfile
        profile_model.objects.using(database).update_or_create(
            slug=curated.slug,
            defaults={
                "user_id": None,
                "name": curated.name,
                "profession": curated.profession,
                "location": curated.location,
                "about": curated.about,
                "expectations": curated.expectations,
                "family": curated.family,
                "image_path": curated.image_path,
                "is_sample": True,
                "is_featured": curated.is_featured,
            },
        )


def restore_curated_profiles(apps, schema_editor):
    CuratedProfile = apps.get_model("main", "CuratedProfile")
    BrideProfile = apps.get_model("main", "BrideProfile")
    GroomProfile = apps.get_model("main", "GroomProfile")
    database = schema_editor.connection.alias

    for gender, profile_model in (("bride", BrideProfile), ("groom", GroomProfile)):
        for profile in profile_model.objects.using(database).filter(is_sample=True):
            CuratedProfile.objects.using(database).update_or_create(
                slug=profile.slug,
                defaults={
                    "gender": gender,
                    "name": profile.name,
                    "profession": profile.profession,
                    "location": profile.location,
                    "about": profile.about,
                    "expectations": profile.expectations,
                    "family": profile.family,
                    "image_path": profile.image_path,
                    "is_featured": profile.is_featured,
                },
            )


